function renderTeenVisualAfterLine(line, index) {
  const heading = line.trim();

  if (heading === "What Does Teen Stress & Anxiety Treatment at Manovaidya Focus On?") {
    return <TeenIconGridBlock key={`visual-${index}`} items={teenStressHighlights} />;
  }

  if (heading === "How Do Teens Experience Stress and Anxiety?") {
    return <TeenSupportVisualsBlock key={`visual-${index}`} />;
  }

  if (heading === "What Are the Common Signs of Teen Stress & Anxiety?") {
    return (
      <TeenImageInfoBlock
        key={`visual-${index}`}
        image={teenSignsImage}
        title="Common Signs of Teen Stress & Anxiety"
        text="Emotional, academic, social and physical signs can appear together. Families can use these signs to understand when support may be needed."
        href="#common-signs"
        Icon={Activity}
      />
    );
  }

  if (heading === "What Is the Neuro-Ayurveda Approach to Teen Stress & Anxiety?") {
    return (
      <TeenImageInfoBlock
        key={`visual-${index}`}
        image={neuroAyurvedaImage}
        title="Neuro-Ayurveda Development System"
        text="A structured framework for brain, gut, sensory, behaviour, routine and family communication patterns."
        href="/about/approach"
        Icon={Brain}
      />
    );
  }

  if (heading === "How Can Parents Support Teenagers?") {
    return (
      <TeenImageInfoBlock
        key={`visual-${index}`}
        image={parentGuidanceImage}
        title="Parent Guidance for Teen Anxiety"
        text="Calm listening, realistic expectations, healthy routines and supportive communication help teenagers feel understood."
        href="/parent-teen-relationship-support"
        Icon={Users}
      />
    );
  }

  if (heading === "How Does Manovaidya Support Teenagers & Families?") {
    return <TeenAssessmentFlowBlock key={`visual-${index}`} />;
  }

  if (heading === "Why Do Families Choose Manovaidya?") {
    return <TeenSupportPointGridBlock key={`visual-${index}`} />;
  }

  return null;
}

